import cv2,numpy as np
im=cv2.imread('first_frame.png'); hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV)
for name,lo,hi in [('green',(35,80,50),(90,255,255)),('blue',(90,80,30),(135,255,255)),('dark',(0,0,0),(180,255,55)),('red',(0,70,30),(12,255,180))]:
 m=cv2.inRange(hsv,np.array(lo),np.array(hi)); n,l,st,c=cv2.connectedComponentsWithStats(m)
 print('\\n',name,'total',np.sum(m>0))
 for i in sorted(range(1,n),key=lambda i:-st[i,4])[:12]:
  if st[i,4]>5: print(st[i].tolist(),np.round(c[i],1).tolist())
 cs,_=cv2.findContours(m,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE)
 for j,cnt in enumerate(sorted(cs,key=cv2.contourArea,reverse=True)[:5]):
  eps=cv2.approxPolyDP(cnt,2,True).reshape(-1,2)
  print('poly',j,cv2.contourArea(cnt),eps.tolist())
# green extent each 8 rows
m=cv2.inRange(hsv,np.array((35,80,50)),np.array((90,255,255)))
for y in range(0,144,4):
 xs=np.where(m[y:y+4].any(0)>0)[0]
 if len(xs): print(y, xs.min(),xs.max(),len(xs))
